local P = {}function P:new(init)  local o = {    im = init.im,    listName = init.listName,    listData = init.initialList,    currentRowIndex = init.initialRowIndex or 1,    wrap = init.enableWrap or false,    rowIndexChangedCallback = init.onRowIndexChanged,    currentColumnIndex = init.initalColumnIndex or 1,    listBinding = "bnd_" .. init.listName .. "_list",    rowIndexBinding = "bnd_" .. init.listName .. "_index",    colIndexBinding = "bnd_" .. init.listName .. "_col_index"  }  setmetatable(o, self)  self.__index = self  o.im.Subscribe(o.rowIndexBinding, function()    o:_publishRowIndex()  end  )  o.im.Subscribe(o.colIndexBinding, function()    o:_publishColumnIndex()  end  )  o.im.Subscribe(o.listBinding, function()    o:_publish()  end  )  o.im.RegisterDataAction(o.rowIndexBinding, "act_next", function()    if o.currentRowIndex < #o.listData then      o:setRowIndex(o.currentRowIndex + 1)    else      assert(o.wrap == true)      o:setRowIndex(1)    end  end  )  o.im.RegisterDataAction(o.rowIndexBinding, "act_previous", function()    if o.currentRowIndex > 1 then      o:setRowIndex(o.currentRowIndex - 1)    else      assert(o.wrap == true)      o:setRowIndex(#o.listData)    end  end  )  o.im.RegisterDataAction(o.colIndexBinding, "act_next", function()    assert(o.currentColumnIndex < #o.listData[1])    o:setColumnIndex(o.currentColumnIndex + 1)  end  )  o.im.RegisterDataAction(o.colIndexBinding, "act_previous", function()    assert(o.currentColumnIndex > 1)    o:setColumnIndex(o.currentColumnIndex - 1)  end  )  o:_updateRowActionStates()  o:_updateColActionStates()  return oendfunction P:setData(newList, newIndex)  self.listData = newList  if newIndex ~= nil then    self:_internalSetRowIndex(newIndex)  end  self:_updateRowActionStates()  self:_updateColActionStates()  self:_publish()endfunction P:setRowIndex(newIndex)  self:_internalSetRowIndex(newIndex)  self:_updateRowActionStates()  self:_publishRowIndex()endfunction P:setColumnIndex(newIndex)  self:_internalSetColumnIndex(newIndex)  self:_updateColActionStates()  self:_publishColumnIndex()endfunction P:getRowIndex()  return self.currentRowIndexendfunction P:getCurrentRow()  return self.listData[self.currentRowIndex]endfunction P:getListData()  return self.listDataendfunction P:_updateRowActionStates()  if #self.listData <= 1 then    self.im.ChangeDataActionState(self.rowIndexBinding, "act_next", self.im.GetActionState("INVALID"))    self.im.ChangeDataActionState(self.rowIndexBinding, "act_previous", self.im.GetActionState("INVALID"))    return  end  if self.wrap == true then    self.im.ChangeDataActionState(self.rowIndexBinding, "act_next", self.im.GetActionState("VALID"))    self.im.ChangeDataActionState(self.rowIndexBinding, "act_previous", self.im.GetActionState("VALID"))    return  end  assert(#self.listData >= 2 and self.wrap == false)  if self.currentRowIndex == 1 then    self.im.ChangeDataActionState(self.rowIndexBinding, "act_next", self.im.GetActionState("VALID"))    self.im.ChangeDataActionState(self.rowIndexBinding, "act_previous", self.im.GetActionState("INVALID"))  elseif self.currentRowIndex == #self.listData then    self.im.ChangeDataActionState(self.rowIndexBinding, "act_next", self.im.GetActionState("INVALID"))    self.im.ChangeDataActionState(self.rowIndexBinding, "act_previous", self.im.GetActionState("VALID"))  else    assert(#self.listData > 2)    self.im.ChangeDataActionState(self.rowIndexBinding, "act_next", self.im.GetActionState("VALID"))    self.im.ChangeDataActionState(self.rowIndexBinding, "act_previous", self.im.GetActionState("VALID"))  endendfunction P:_updateColActionStates()  if self.listData == nil or #self.listData == 0 then    self.im.ChangeDataActionState(self.colIndexBinding, "act_next", self.im.GetActionState("INVALID"))    self.im.ChangeDataActionState(self.colIndexBinding, "act_previous", self.im.GetActionState("INVALID"))    return  end  local numColumns = #self.listData[1]  if numColumns <= 1 then    self.im.ChangeDataActionState(self.colIndexBinding, "act_next", self.im.GetActionState("INVALID"))    self.im.ChangeDataActionState(self.colIndexBinding, "act_previous", self.im.GetActionState("INVALID"))    return  end  assert(numColumns >= 2)  assert(1 <= self.currentColumnIndex)  assert(numColumns >= self.currentColumnIndex)  if self.currentColumnIndex == 1 then    self.im.ChangeDataActionState(self.colIndexBinding, "act_previous", self.im.GetActionState("INVALID"))  else    self.im.ChangeDataActionState(self.colIndexBinding, "act_previous", self.im.GetActionState("VALID"))  end  if self.currentColumnIndex == numColumns then    self.im.ChangeDataActionState(self.colIndexBinding, "act_next", self.im.GetActionState("INVALID"))  else    self.im.ChangeDataActionState(self.colIndexBinding, "act_next", self.im.GetActionState("VALID"))  endendfunction P:_internalSetRowIndex(newIndex)  self.currentRowIndex = newIndex  if self.rowIndexChangedCallback ~= nil then    self.rowIndexChangedCallback(self)  endendfunction P:_internalSetColumnIndex(newIndex)  self.currentColumnIndex = newIndexendfunction P:_publish()  self.im.Publish(self.listBinding, {    index = self.currentRowIndex - 1,    columnIndex = self.currentColumnIndex - 1,    data = self.listData  })endfunction P:_publishRowIndex()  self.im.Publish(self.rowIndexBinding, self.currentRowIndex - 1)endfunction P:_publishColumnIndex()  self.im.Publish(self.colIndexBinding, self.currentColumnIndex - 1)endfunction P:finalize()  self.im.Unsubscribe(self.listBinding)  self.im.Unsubscribe(self.colIndexBinding)  self.im.Unsubscribe(self.rowIndexBinding)  self.im.UnregisterDataAction(self.rowIndexBinding, "act_next")  self.im.UnregisterDataAction(self.rowIndexBinding, "act_previous")  self.im.UnregisterDataAction(self.colIndexBinding, "act_next")  self.im.UnregisterDataAction(self.colIndexBinding, "act_previous")endreturn P